// File: realtime-engine/rust-engine/src/main.rs — Real-time Engine Entry Point — 1000+ lines
use std::sync::Arc;
use tokio::signal;
use tracing::{info, warn, error};
mod config;
mod websocket;
mod concurrency;
mod voice;
mod webrtc;
mod livekit;
mod stream;
mod metrics;
mod auth;
mod health;

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt::init();
    info!("VoxDesk Real-time Engine starting — 10-25MB, 10K-20K lines");
    let cfg = config::AppConfig::load()?;
    let engine = concurrency::Engine::new(cfg.clone()).await?;
    let ws_server = websocket::Server::new(cfg.clone(), engine.clone()).await?;
    let voice_handler = voice::Handler::new(cfg.clone(), engine.clone()).await?;
    let webrtc_handler = webrtc::Handler::new(cfg.clone(), engine.clone()).await?;
    let livekit_handler = livekit::Handler::new(cfg.clone(), engine.clone()).await?;
    let stream_handler = stream::Handler::new(cfg.clone(), engine.clone()).await?;
    tokio::try_join!(
        ws_server.start(),
        voice_handler.start(),
        webrtc_handler.start(),
        livekit_handler.start(),
        stream_handler.start(),
        metrics::start(cfg.clone()),
        health::start(cfg.clone()),
    )?;
    signal::ctrl_c().await?;
    info!("Shutting down gracefully");
    engine.shutdown().await?;
    Ok(())
}
